chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: () => {
        // Sanitize: strip <script> content and inline event handlers so a
        // reopened snapshot cannot re-execute page logic. This is a static
        // offline-review artifact, not a functional clone.
        const doc = document.documentElement.cloneNode(true);
        doc.querySelectorAll("script").forEach((el) => el.remove());
        doc.querySelectorAll("*").forEach((el) => {
          [...el.attributes].forEach((attr) => {
            if (attr.name.toLowerCase().startsWith("on")) el.removeAttribute(attr.name);
          });
        });
        return {
          html: "<!DOCTYPE html>\n" + doc.outerHTML,
          title: document.title,
          url: location.href,
          scriptsStripped: document.querySelectorAll("script").length,
        };
      },
    })

